# generated by tools/ail2py.py from config_core.ail; edit the .ail until onelang s16
from checked_integer import *
from ail import open_binary
def config_text(path: str) -> str:
    try:
        reader = open_binary(path, 'r')
        try:
            data: bytes = b''
            while True:
                block: bytes = reader.read(8192)
                if len(block) == 0:
                    break
                data += block
            return data.decode()
        finally:
            reader.close()
    except OSError:
        raise OSError('file error')
    except UnicodeDecodeError:
        raise UnicodeDecodeError('input must be UTF-8')

def config_report(text: str) -> str:
    count: int = 0
    total: int = 0
    number: int = 0
    for raw in text.splitlines():
        number += 1
        line: str = raw.strip()
        if line == '' or line.startswith('#'):
            continue
        prefix: str = 'line ' + str(number) + ': '
        parts: list[str] = line.split('=')
        if len(parts) != 2:
            raise ValueError(prefix + 'expected key=integer')
        key: str = parts[0].strip()
        token: str = parts[1].strip()
        if key == '':
            raise ValueError(prefix + 'empty key')
        value: int = 0
        try:
            value = parse_int64_decimal(token)
        except ValueError:
            raise ValueError(prefix + 'invalid integer: ' + token)
        try:
            total = checked_int64_add(total, value)
        except ValueError:
            raise ValueError(prefix + 'total outside int64')
        count += 1
    return '{"count":' + str(count) + ',"total":' + str(total) + '}'

def validate_config(path: str) -> str:
    try:
        return config_report(config_text(path))
    except ValueError as e:
        raise e
    except OSError:
        raise
